-- =============================================================================
-- V141 — Maharashtra geography: 34 districts, 361 talukas (as cities),
-- post offices (as areas) and 1580 pincodes, in the platform's global masters.
--
-- Source: the India Post pincode directory published on data.gov.in (districts, post offices),
-- with each pincode's taluka from the same directory's taluka listing. Generated, do not edit.
--
-- Safe on a database that already has some of this: every country, state, district and city is
-- looked up by name first and reused (names compare case-insensitively, as the postal lookup's
-- auto-create does). A pincode already on file is left exactly as it is, with its areas; only
-- missing pincodes are added, each with its post offices as areas (the first is its primary
-- area). Generated codes carry a short hash so they cannot collide with existing ones.
-- =============================================================================

SET @p = UNHEX('00000000000000000000000000000001');

INSERT INTO master_countries (id, company_id, code, name, status, display_order, iso_code2, iso_code3, dial_code, currency_code, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'INDIA_8E68B3', 'India', 'ACTIVE', 0, 'IN', 'IND', '+91', 'INR', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_countries WHERE company_id = @p AND name = 'India');
SET @country = (SELECT id FROM master_countries WHERE company_id = @p AND name = 'India' ORDER BY deleted, created_at LIMIT 1);

INSERT INTO master_states (id, company_id, code, name, status, display_order, country_id, gst_state_code, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, 'MAHARASHTRA_AA4A5F', 'Maharashtra', 'ACTIVE', 0, @country, '27', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM master_states WHERE company_id = @p AND country_id = @country AND name = 'Maharashtra');
SET @state = (SELECT id FROM master_states WHERE company_id = @p AND country_id = @country AND name = 'Maharashtra' ORDER BY deleted, created_at LIMIT 1);

INSERT INTO master_districts (id, company_id, code, name, status, display_order, state_id, created_at, updated_at, deleted, version)
