FROM (SELECT * FROM (VALUES ROW('Chinchwad East', 'A411019_DEBA056B'), ROW('M.Phulenagar', 'A411019_DCEBB534')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '411019')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c248 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
