FROM (SELECT * FROM (VALUES ROW('Ane', 'A412410_874C8F71'), ROW('Belha', 'A412410_2ADF3E50'), ROW('Mangrul', 'A412410_421E0E46'), ROW('Nalavane', 'A412410_06906E81'), ROW('Sakori Tarfe Belha', 'A412410_075B3E77')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '412410')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c244 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
INSERT INTO master_pincodes (id, company_id, code, name, description, status, display_order, area_id, serviceable, cod_available, prepaid_available, pickup_available, oda_applicable, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, '412410', 'Belha', 'Imported from the India Post pincode directory (V141)', 'ACTIVE', 0, a.id, TRUE, TRUE, TRUE, TRUE, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c244 AND a.name = 'Belha' AND NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '412410')
