FROM (SELECT * FROM (VALUES ROW('Bankot', 'A415208_24161197'), ROW('Devhare', 'A415208_A59F158A'), ROW('Gothe', 'A415208_E85F92A7'), ROW('Nigadi', 'A415208_9CE2ADD2'), ROW('Shipole', 'A415208_61331A97'), ROW('Umroli', 'A415208_B5C39C4F'), ROW('Velas', 'A415208_2747C50B'), ROW('Veshvi', 'A415208_828F0D85')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '415208')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c273 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
INSERT INTO master_pincodes (id, company_id, code, name, description, status, display_order, area_id, serviceable, cod_available, prepaid_available, pickup_available, oda_applicable, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, '415208', 'Veshvi', 'Imported from the India Post pincode directory (V141)', 'ACTIVE', 0, a.id, TRUE, TRUE, TRUE, TRUE, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c273 AND a.name = 'Veshvi' AND NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '415208')
ORDER BY a.deleted, a.created_at LIMIT 1;
INSERT INTO master_pincode_areas (id, company_id, pincode_id, area_id, is_primary, oda_applicable, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, pin.id, a.id, a.id = pin.area_id, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM master_pincodes pin JOIN master_areas a ON a.company_id = @p AND a.city_id = @c273 AND a.deleted = FALSE
WHERE pin.company_id = @p AND pin.code = '415208' AND pin.description = 'Imported from the India Post pincode directory (V141)'
  AND a.name IN ('Bankot', 'Devhare', 'Gothe', 'Nigadi', 'Shipole', 'Umroli', 'Velas', 'Veshvi')
  AND NOT EXISTS (SELECT 1 FROM master_pincode_areas x WHERE x.company_id = @p AND x.pincode_id = pin.id AND x.area_id = a.id);
