FROM (SELECT * FROM (VALUES ROW('Chipri', 'A416101_F00E1915'), ROW('Danoli', 'A416101_1A0727D5'), ROW('Jaisingpur R.S.', 'A416101_0FEDC8BC'), ROW('Jaysingpur', 'A416101_3443B942'), ROW('Kothali', 'A416101_50AE9612'), ROW('Nimshirgaon', 'A416101_9C935607'), ROW('Tamadalage', 'A416101_7CEAF36A'), ROW('Udgaon', 'A416101_FE822C63'), ROW('Umalwad', 'A416101_EB460BEF')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '416101')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c156 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
