FROM (SELECT * FROM (VALUES ROW('Bagani', 'A416302_76DE5E1F'), ROW('Bhadkimbe', 'A416302_5347FD1E'), ROW('Dhavali', 'A416302_A9088EFB'), ROW('Koregaon', 'A416302_47F76BA3'), ROW('Nagaon', 'A416302_67A50B15'), ROW('Shigaon', 'A416302_4F8AFF90')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '416302')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c285 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
INSERT INTO master_pincodes (id, company_id, code, name, description, status, display_order, area_id, serviceable, cod_available, prepaid_available, pickup_available, oda_applicable, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, '416302', 'Bagani', 'Imported from the India Post pincode directory (V141)', 'ACTIVE', 0, a.id, TRUE, TRUE, TRUE, TRUE, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c285 AND a.name = 'Bagani' AND NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '416302')
ORDER BY a.deleted, a.created_at LIMIT 1;
INSERT INTO master_pincode_areas (id, company_id, pincode_id, area_id, is_primary, oda_applicable, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, pin.id, a.id, a.id = pin.area_id, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
FROM master_pincodes pin JOIN master_areas a ON a.company_id = @p AND a.city_id = @c285 AND a.deleted = FALSE
WHERE pin.company_id = @p AND pin.code = '416302' AND pin.description = 'Imported from the India Post pincode directory (V141)'
  AND a.name IN ('Bagani', 'Bhadkimbe', 'Dhavali', 'Koregaon', 'Nagaon', 'Shigaon')
  AND NOT EXISTS (SELECT 1 FROM master_pincode_areas x WHERE x.company_id = @p AND x.pincode_id = pin.id AND x.area_id = a.id);
