FROM (SELECT * FROM (VALUES ROW('Balgaon', 'A416413_2BB61725'), ROW('Bellondagi', 'A416413_8C8AB5ED'), ROW('Boblad Jadar', 'A416413_2BC573B7'), ROW('Borgi(Khurd)', 'A416413_24EAFA86'), ROW('Girgaon', 'A416413_234F6A48'), ROW('Madgyal', 'A416413_21DF8E4D'), ROW('Sonyal', 'A416413_C6BA0F38'), ROW('Suslad', 'A416413_FE8EB1C8'), ROW('Umadi', 'A416413_8903D53A'), ROW('Utagi', 'A416413_921CEA4E'), ROW('Vhaspet', 'A416413_DCD948A5')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '416413')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c278 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
