FROM (SELECT * FROM (VALUES ROW('Ahiwantwadi', 'A422215_61EF178E'), ROW('Bhatode', 'A422215_3C81B1DE'), ROW('Chausale', 'A422215_1A21C27E'), ROW('Haste', 'A422215_27B44B7B'), ROW('Maledumala', 'A422215_E44F0865'), ROW('Mavdi', 'A422215_B2640563'), ROW('Pandane', 'A422215_E866A86E'), ROW('Paregaon', 'A422215_DAB96FD3'), ROW('Pimpri -achala', 'A422215_C3AA42EE'), ROW('Shivre', 'A422215_AC036B3F'), ROW('Vani', 'A422215_D8837685')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '422215')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c202 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
INSERT INTO master_pincodes (id, company_id, code, name, description, status, display_order, area_id, serviceable, cod_available, prepaid_available, pickup_available, oda_applicable, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), @p, '422215', 'Vani', 'Imported from the India Post pincode directory (V141)', 'ACTIVE', 0, a.id, TRUE, TRUE, TRUE, TRUE, FALSE, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), FALSE, 0
