FROM (SELECT * FROM (VALUES ROW('Armori', 'A441208_13C94C3D'), ROW('Arsoda', 'A441208_24F89E4D'), ROW('Churmura', 'A441208_59CB765C'), ROW('Deulgaon', 'A441208_79622C9C'), ROW('Jogisakhara', 'A441208_99A85866'), ROW('Shioni BK', 'A441208_F9756873'), ROW('Thanegaon', 'A441208_897DA10A'), ROW('Wasala', 'A441208_AB8639BD')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '441208')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c99 AND a.name = x.name)
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.code = x.code);
