FROM (SELECT * FROM (VALUES ROW('Borala', 'A444808_E0BF656A'), ROW('Kakda', 'A444808_82FB50CA'), ROW('Kolha', 'A444808_D7F2FC4B'), ROW('Kushta BK', 'A444808_181F4FE5'), ROW('Morgad', 'A444808_B8C9FDFB'), ROW('Pandhari', 'A444808_C67AAD08'), ROW('Parasapur', 'A444808_B92C94F9'), ROW('Pathrot', 'A444808_18C75DB2'), ROW('Sindi BK', 'A444808_E6CA3273'), ROW('Sonapur', 'A444808_45F2827B'), ROW('Tawlar', 'A444808_046D313F'), ROW('Wadgaon Fatepur', 'A444808_804EFFC7')) AS v(name, code)) x
WHERE NOT EXISTS (SELECT 1 FROM master_pincodes WHERE company_id = @p AND code = '444808')
  AND NOT EXISTS (SELECT 1 FROM master_areas a WHERE a.company_id = @p AND a.city_id = @c24 AND a.name = x.name)
